<template>
  <div class="face-register">
    <el-dialog title="注册新人脸" append-to-body width="900px" :visible.sync="dialogFormVisible" @opened="onDialogOpened" @closed="onDialogClosed">
      <!-- 设备选择 -->
      <div class="device-select-bar">
        <span class="label">{{ $t('devtable.sbxlh') }}：</span>
        <el-select v-model="selectedDeviceId" :placeholder="$t('devtable.qxz')" size="small" @change="onDeviceChange" style="width: 260px;" :disabled="!!presetDeviceId">
          <el-option
            v-for="item in deviceList"
            :key="item.id"
            :label="item.name"
            :value="item.id">
          </el-option>
        </el-select>
      </div>

      <!-- 搜索表单 -->
      <div class="search-bar">
        <el-form :inline="true" size="small">
          <el-form-item :label="$t('devtable.xm')">
            <el-input v-model="searchName" :placeholder="$t('devtable.xm')"></el-input>
          </el-form-item>
          <el-form-item :label="$t('devtable.sjhm')">
            <el-input v-model="searchMobile" :placeholder="$t('devtable.sjhm')"></el-input>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click="onSearch" :disabled="!selectedDeviceId">{{ $t('devtable.cx') }}</el-button>
          </el-form-item>
        </el-form>
      </div>

      <!-- 用户表格 -->
      <el-table :data="tableData" border v-loading="loading" style="width: 100%;">
        <el-table-column prop="name" :label="$t('devtable.xm')" align="center"></el-table-column>
        <el-table-column prop="mobile" :label="$t('devtable.sjhm')" align="center"></el-table-column>
        <el-table-column :label="$t('devtable.tbzt')" align="center">
          <template slot-scope="scope">
            <el-tag v-if="scope.row.registering" type="warning">注册中</el-tag>
            <el-tag v-else-if="scope.row.state === 1" type="success">成功</el-tag>
            <el-tag v-else-if="scope.row.state === 2" type="danger">失败</el-tag>
            <el-tag v-else type="info">未注册</el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="$t('devtable.qxck')" align="center" width="380">
          <template slot-scope="scope">
            <el-button
              type="primary"
              size="mini"
              :disabled="scope.row.registering || scope.row.state === 1"
              @click="handleRegister(scope.row)"
            >注册人脸</el-button>
            <el-button
              type="danger"
              size="mini"
              :disabled="scope.row.state !== 1"
              @click="handleDelete(scope.row)"
            >删除人脸</el-button>
            <el-button
              type="info"
              size="mini"
              @click="handleCheckStatus(scope.row)"
            >状态查询</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页 -->
      <div style="margin-top: 20px; text-align: right;">
        <el-pagination
          @size-change="handleSizeChange"
          @current-change="handlePageChange"
          :current-page="page_index"
          :page-sizes="[10, 20, 30, 40]"
          :page-size="page_size"
          layout="total, sizes, prev, pager, next, jumper"
          :total="total">
        </el-pagination>
      </div>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'FaceRegister',
  data() {
    return {
      dialogFormVisible: false,
      presetDeviceId: null,
      deviceList: [],
      selectedDeviceId: '',
      searchName: '',
      searchMobile: '',
      tableData: [],
      loading: false,
      page_index: 1,
      page_size: 10,
      total: 0,
      UserInfo: null,
      pollingTimer: null
    }
  },
  beforeDestroy() {
    this.stopPolling()
  },
  methods: {
    // 打开弹窗，可传入设备信息预选设备
    show(device) {
      this.UserInfo = JSON.parse(window.localStorage.getItem('user'))
      if (device) {
        this.presetDeviceId = device.id
      } else {
        this.presetDeviceId = null
      }
      this.searchName = ''
      this.searchMobile = ''
      this.page_index = 1
      this.tableData = []
      this.total = 0
      this.dialogFormVisible = true
    },
    // 弹窗打开后加载数据
    onDialogOpened() {
      this.getDeviceList().then(() => {
        if (this.presetDeviceId) {
          this.selectedDeviceId = this.presetDeviceId
          this.getUserList()
        }
      })
    },
    // 弹窗关闭后清理
    onDialogClosed() {
      this.stopPolling()
      this.selectedDeviceId = ''
      this.presetDeviceId = null
    },
    // 获取设备列表
    getDeviceList() {
      return this.$faceRegister({
        method: 'co.fg.device.list',
        agent_id: this.UserInfo.agent_id
      }).then(res => {
        if (res.data.code === 0) {
          this.deviceList = res.data.data || []
        }
      })
    },

    // 切换设备
    onDeviceChange() {
      this.page_index = 1
      this.getUserList()
    },

    // 搜索
    onSearch() {
      this.page_index = 1
      this.getUserList()
    },

    // 获取用户列表
    getUserList() {
      if (!this.selectedDeviceId) {
        this.$message.warning('请先选择设备')
        return
      }
      this.loading = true
      this.$faceRegister({
        method: 'co.fg.user.list',
        agent_id: this.UserInfo.agent_id,
        device_id: this.selectedDeviceId,
        page_index: this.page_index,
        page_size: this.page_size,
        name: this.searchName,
        mobile: this.searchMobile
      }).then(res => {
        this.loading = false
        if (res.data.code === 0) {
          this.tableData = (res.data.data || []).map(item => ({
            ...item,
            registering: false
          }))
          this.total = res.data.count || 0
        }
      }).catch(() => {
        this.loading = false
      })
    },

    // 注册人脸
    handleRegister(row) {
      this.$confirm('确认为该用户注册人脸到当前设备？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        row.registering = true
        this.$faceRegister({
          method: 'co.person.reg.fg.face',
          user_id: row.id,
          agent_id: this.UserInfo.agent_id,
          device_id: this.selectedDeviceId
        }).then(res => {
          row.registering = false
          if (res.data.code === 0) {
            this.$message.success('注册成功')
            this.pollRegistrationStatus(row)
          } else {
            this.$message.error(res.data.message || '注册失败')
          }
        }).catch(() => {
          row.registering = false
          this.$message.error('注册请求失败')
        })
      }).catch(() => {})
    },

    // 删除人脸
    handleDelete(row) {
      this.$confirm('确认删除该用户的人脸信息？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.$faceRegister({
          method: 'co.person.del.fg.face',
          device_id: this.selectedDeviceId,
          user_id: row.id
        }).then(res => {
          if (res.data.code === 0) {
            this.$message.success('删除成功')
            row.state = 0
          } else {
            this.$message.error(res.data.message || '删除失败')
          }
        }).catch(() => {
          this.$message.error('删除请求失败')
        })
      }).catch(() => {})
    },

    // 查询注册状态
    handleCheckStatus(row) {
      this.$faceRegister({
        method: 'co.reg.face.state.get',
        user_id: row.id,
        device_id: this.selectedDeviceId
      }).then(res => {
        if (res.data.code === 0) {
          const status = parseInt(res.data.data)
          // 更新本地行状态：成功=1，失败=2，默认=0
          this.$set(row, 'state', status)
          const statusText = status === 1 ? '注册成功' : status === 2 ? '注册失败' : '默认'
          this.$message.info('当前状态：' + statusText)
        }
      })
    },

    // 轮询注册状态
    pollRegistrationStatus(row) {
      this.stopPolling()
      let pollCount = 0
      const maxPolls = 20
      this.pollingTimer = setInterval(() => {
        pollCount++
        this.$faceRegister({
          method: 'co.reg.face.state.get',
          user_id: row.id,
          device_id: this.selectedDeviceId
        }).then(res => {
          if (res.data.code === 0) {
            const status = parseInt(res.data.data)
            this.$set(row, 'state', status)
            if (status === 1) {
              this.$message.success(row.name + ' 人脸注册成功！')
              this.stopPolling()
            } else if (status === 2) {
              this.$message.error(row.name + ' 人脸注册失败')
              this.stopPolling()
            }else{
              this.$message.info('当前状态：' + statusText)
              this.stopPolling()
            }
          }
          if (pollCount >= maxPolls) {
            this.stopPolling()
            this.$message.warning('状态查询超时，请手动查询')
          }
        })
      }, 3000)
    },

    stopPolling() {
      if (this.pollingTimer) {
        clearInterval(this.pollingTimer)
        this.pollingTimer = null
      }
    },

    // 分页
    handleSizeChange(val) {
      this.page_size = val
      this.page_index = 1
      this.getUserList()
    },

    handlePageChange(val) {
      this.page_index = val
      this.getUserList()
    }
  }
}
</script>

<style lang="less" scoped>
.face-register {
  padding: 20px;
  background-color: #fff;

  .device-select-bar {
    margin-bottom: 20px;
    padding: 15px 20px;
    background: #f5f7fa;
    border-radius: 4px;

    .label {
      margin-right: 10px;
      font-size: 14px;
      color: #606266;
    }
  }

  .search-bar {
    margin-bottom: 15px;
  }
}
</style>
